ead><tbody><?php foreach($data['cohorts'] as $b):if($sku!==''&&$sku!==$b['sku'])continue;foreach($b['sizes'] as $size=>$counts):?><tr><th><?=h($b['sku'])?></th><td><?=$b['height']?>–<?=$b['height']+4?> cm</td><td><?=$b['weight']?>–&lt;<?=$b['weight']+5?> kg</td><td><?=h($size)?></td><td><?=$counts['accepted']?></td><td><?=$counts['returned']?></td></tr><?php endforeach;endforeach;?></tbody></table></div></details></main><script type="module" src="date-picker.js?v=22"></script></body></html>
